 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # Markers embedded in the horizontal baseline project upward as a short stem:
    # marker at the top, followed by two cells of color 1 down to the baseline.
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value in (2, 8):
                for dr, color in ((3, value), (2, 1), (1, 1)):
                    rr = r - dr
                    if rr >= 0:
                        out[rr][c] = color
    return out
